arguments.command:
cat > /tmp/scratchpad/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) echo "x-access-token" ;;
*Password*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/scratchpad/askpass.sh
cd /tmp/scratchpad/chandler && GIT_ASKPASS=/tmp/scratchpad/askpass.sh git push origin HEAD:refs/heads/friend/chandler 2>&1 | tail
